    var pay = o.paidAt ? depDoc+'<div class="doc" style="border-color:var(--green)"><span class="ico">✓</span><span><strong>'+(o.depositAt?'Balance paid '+BS.fmt((o.paidTotal||ex.total)-(o.depositAmt||0)-(o.lateFee||0)):'Paid '+BS.fmt(o.paidTotal||ex.total))+'</strong><br><span class="small muted">'+when(o.paidAt)+' · '+esc(o.paymentMethod||'Yagout Pay')+' · '+esc(o.paymentRef)+'</span></span><button class="btn btn-ghost btn-sm" type="button" data-doc="receipt">Receipt</button></div>'
      : (role==='buyer' && BS.payOpen(o)) ? depDoc+'<div class="payform"><div><strong>'+(stage==='deposit'?'Pay the deposit ('+(+term.pct||BS.DEPOSIT_PCT)+'%)':stage==='balance'?'Pay the balance':'Pay the full amount')+'</strong><p class="small muted">Telebirr, CBE Birr and cards go through the Yagout Pay gateway; a bank transfer goes to the Build Smartly account.</p></div><div class="su-choices">'+methods.map(function(m,i){ return '<div class="choice"><input type="radio" name="opayM" id="opm'+i+'" value="'+m[1]+'"'+(m[1]===payMethod?' checked':'')+'><label for="opm'+i+'"><strong>'+m[1]+'</strong><span>'+m[2]+'</span></label></div>'; }).join('')+'</div>'+bankInfo+'<label class="check"><input type="checkbox" id="payAgree"><span>I authorise '+BS.fmt(dueAmt)+' for this order.</span></label><div class="btns"><button class="btn btn-ochre" type="button" data-paynow="'+o.id+'">Pay '+BS.fmt(dueAmt)+'</button>'+(window.bsDueCount && bsDueCount()>1 ? '<button class="btn btn-ghost" type="button" data-payall>Pay all '+bsDueCount()+' orders due together</button>' : '')+'</div></div>'
      : depDoc+'<p class="small muted">'+(BS.payOpen(o)?'Waiting for the buyer\'s '+(stage==='deposit'?'deposit.':stage==='balance'?'balance.':'payment.'):!o.contractAt?(term.kind==='before'||term.kind==='deposit'?(term.kind==='deposit'?'The deposit':'Payment')+' opens when the supplier confirms the PO/SA.':'Payment opens after the buyer checks the items.'):term.kind==='credit'?'Payment opens after the buyer checks the items; due within '+(+term.days||BS.CREDIT_MAX)+' days of delivery.':term.kind==='deposit'&&o.depositAt?'The balance opens after the buyer checks the items.':'Payment opens after the buyer checks the items.')+'</p>';
    /* item check after the handover */
    var check = o.deliveredAt ? card('Check your items', checkHtml(g, b, role, o), role==='buyer'&&!BS.isChecked(o)?'One answer per item. Items you do not answer by <span data-notr>'+when(new Date(cdue).toISOString())+'</span> count as received.':'', 'orderCheck') : '';
    /* messages: kept on the first line's id so older threads still show */
    var gids=ids(g); var msgs=data.messages.filter(function(m){ return gids.indexOf(m.orderId)>=0; }).sort(function(a,c){ return (a.createdAt||'').localeCompare(c.createdAt||''); });
    var chat='<div class="chat" id="orderChat">'+(msgs.length?msgs.map(function(m){ var mine = m.who===role; return '<div class="msg '+(mine?'me':'')+'"><div class="t">'+(m.who==='buyer'?esc(buyerName||'Buyer'):m.who==='supplier'?esc(supName):'Build Smartly staff')+' · '+when(m.createdAt)+'</div>'+esc(m.text)+'</div>'; }).join(''):'<div class="empty">No messages yet. The other party and Build Smartly staff see what you write here.</div>')+'</div><div class="chat-in"><div class="field"><input id="orderMsgIn" placeholder="Message '+esc(role==='buyer'?'the supplier':role==='supplier'?'the buyer':'both parties')+'…"></div><button class="btn btn-primary btn-sm" type="button" data-msg="'+o.id+'">Send</button></div>';
    var iss=data.issues.filter(function(x){ return gids.indexOf(x.offerId)>=0; }).sort(function(a,c){ return (c.createdAt||'').localeCompare(a.createdAt||''); });
    var issues=(iss.length?'<div class="docs">'+iss.map(function(x){ return '<div class="doc"><span class="ico">!</span><span><strong>'+esc(x.text)+'</strong>'+(x.photo?'<br><img class="chkphoto" src="'+x.photo+'" alt="">':'')+'<br><span class="small muted">'+esc(x.who)+' · '+when(x.createdAt)+(x.status==='resolved'?' · resolved: '+esc(x.note||''):'')+'</span></span>'+(x.status==='resolved'?'<span class="tag tag-green">Resolved</span>':x.status==='progress'?'<span class="tag tag-ochre">In progress</span>':role==='staff'?'<span style="display:flex;gap:.3rem"><input placeholder="Resolution note" data-note="'+x.id+'" style="font:inherit;font-size:.85rem;padding:.35rem .5rem;border:1.5px solid var(--line);border-radius:8px;min-width:10rem"><button class="btn btn-primary btn-sm" type="button" data-resolve="'+x.id+'">Resolve</button></span>':'<span class="tag tag-ochre">Open · staff told</span>')+'</div>'; }).join('')+'</div>':'')+
      (role!=='staff'?'<div class="chat-in"><div class="field"><input id="orderIssueIn" placeholder="Wrong quantity, damage, delay…"></div><button class="btn btn-ghost btn-sm" type="button" data-issue="'+o.id+'">Report</button></div>':'');
    var track=(o.dispatchedAt && o.trackId) ? card('Delivery tracking', '<div id="trackCard"></div>', '', 'orderTrack') : '';
    /* handover codes: one card, each code with who uses it, so nobody types the wrong one */
    var codes='';
