      var cBuyer='<div class="codebox"><span class="codelbl">'+(role==='buyer'?'Your handover code':'Buyer\'s handover code')+'</span><strong class="codeval" data-notr>'+esc(o.handoverCode||'')+'</strong><span class="small">'+(role==='buyer'?'Check the goods first, then tell this code to the driver. The driver types it on his phone. Giving it is your signature that you received the goods.':'The buyer tells it to the driver after checking the goods; the driver types it on the tracking page.')+'</span></div>';
      var cNote='<div class="codebox"><span class="codelbl">Delivery note code</span><strong class="codeval" data-notr>'+esc(o.noteCode||'')+'</strong><span class="small">Printed on the delivery note the driver carries. Used only when the driver has no working phone: the buyer types it on this page.</span><button class="btn btn-ghost btn-sm" type="button" data-doc="note">Open the delivery note</button></div>';
      var cType=(role==='buyer')?'<div class="codebox"><span class="codelbl">Driver has no working phone?</span><span class="small">Ask the driver for the delivery note and type the 4-digit code printed on it. Not your own code.</span><div class="chat-in"><div class="field"><input id="rcvCode" inputmode="numeric" maxlength="4" placeholder="Code printed on the delivery note" autocomplete="off"></div><button class="btn btn-primary btn-sm" type="button" data-received="'+o.id+'">Goods handed over</button></div></div>':'';
