    box.innerHTML=head+parties+card('What happens next', next, '', 'orderNext').replace('class="card ocard"', yourTurn?'class="card ocard act"':'class="card ocard"')+((role==='buyer' && o.deliveredAt && !BS.isChecked(o))?check.replace('class="card ocard"','class="card ocard act"'):check)+codes+track+card('Items', items)+'<div class="ogrid ocols"><div class="ocol">'+card('Payment', payRows+pay, '', 'orderPay')+card('Progress', tl, '', 'orderProg')+card('Messages', chat, '', 'orderMsgs')+hist+'</div><div class="ocol">'+card('Delivery', delivery, '', 'orderDeliv')+card('Documents', docs, '', 'orderDocs')+amd+staffAct+card('Report a problem', issues||'<p class="small muted">Nothing reported.</p>', '', 'orderIssue')+'</div></div>';
    var chatEl=$('orderChat'); if(chatEl) chatEl.scrollTop=chatEl.scrollHeight;
    Object.keys(keep).forEach(function(k){ var el=$(k); if(el) el.value=keep[k]; }); if(focusId && keep[focusId]!==undefined && $(focusId)) $(focusId).focus();
